3	/// An item a policy covers, as the office records it: the type it is listed
4	/// under in the price list, and the properties its clauses judge. The office
5	/// records an item's material because its reimbursement clauses speak of
6	/// items made of dragon material, and it is on the record of every insured
7	/// item whatever the clauses do with it. No clause reads the material: the
8	/// dragon-material clause reimburses in full, which is already what the
9	/// office admits when no clause reduces the damage, and where the clause
10	/// meets the enchantment clause the enchantment clause wins -- see
11	/// `reimbursable_damage_of`.
12	struct Item {
13	    item_type: String,
14	    cursed: bool,
15	    enchantment: i64,
16	    #[allow(dead_code, reason = "on the record of every insured item; no clause reads it")]
17	    material: String,
18	}
19	
20	const PROCESSING_FEE: i64 = 5;
21	
22	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
23	const CURSE_SURCHARGE: f64 = 0.50;
24	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
25	const LOYALTY_DISCOUNT: f64 = 0.20;
26	const LOYALTY_YEARS: i64 = 2;
27	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
28	const HIGH_ENCHANTMENT_SURCHARGE_LEVEL: i64 = 5;
29	
30	const SWORD_BASE_PREMIUM: f64 = 100.0;
31	const AMULET_BASE_PREMIUM: f64 = 60.0;
32	const STAFF_BASE_PREMIUM: f64 = 80.0;
33	const POTION_BASE_PREMIUM: f64 = 40.0;
34	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
35	const SWORD_INSURANCE_VALUE: i64 = 1000;
36	const AMULET_INSURANCE_VALUE: i64 = 600;
37	const STAFF_INSURANCE_VALUE: i64 = 800;
38	const POTION_INSURANCE_VALUE: i64 = 400;
39	const COMPONENT_INSURANCE_VALUE: i64 = 250;
40	const PAYOUT_CAP_FACTOR: i64 = 2;
41	const DEDUCTIBLE: i64 = 100;
42	const HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL: i64 = 8;
43	const HIGH_ENCHANTMENT_REIMBURSEMENT: f64 = 0.50;
44	const COMPONENT_BLOCK_SIZE: usize = 3;
45	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
46	
47	/// The MHPCO treats components -- runes and moonstones -- as a category of
48	/// their own, priced per component rather than per type. Component types enter
49	/// this predicate with their examples.
50	fn is_component(item: &Item) -> bool {
51	    matches!(item.item_type.as_str(), "rune" | "moonstone")
52	}
53	
54	/// The MHPCO insures the item types its price list names and no others.
55	fn is_in_the_price_list(item_type: &str) -> bool {
56	    matches!(
57	        item_type,
58	        "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone"
59	    )
60	}
61	
62	/// The MHPCO price list: the base premium in G for a single insured item. Main
63	/// item types are listed individually; every component carries the same flat
64	/// component premium. All four main types now have their examples, and a quote
65	/// over an unlisted type is refused before it reaches the list, so the
66	/// remaining arm prices the sword and nothing else -- it is written as a
67	/// fall-through rather than as a `"sword"` arm because the list is closed and a
68	/// `"sword"` arm would leave an unreachable residual behind it.
69	fn base_premium_of(item: &Item) -> f64 {
70	    if is_component(item) {
71	        return COMPONENT_BASE_PREMIUM;
72	    }
73	    match item.item_type.as_str() {
74	        "amulet" => AMULET_BASE_PREMIUM,
75	        "staff" => STAFF_BASE_PREMIUM,
76	        "potion" => POTION_BASE_PREMIUM,
77	        _ => SWORD_BASE_PREMIUM,
78	    }
79	}
80	
81	/// What the customer's standing with the office is worth, as a single share of
82	/// the policy base premium. The office was asked whether "first insurance"
83	/// means the customer's first ever contract or the first time it sees this
84	/// item, and ruled for the item: every item in a quote is treated as a first
85	/// insurance, so the initial assessment surcharge is unconditional and a
86	/// long-standing customer pays it on a brand-new sword like anyone else. What
87	/// the years of business earn is the loyalty discount, taken against that
88	/// surcharge. This is the office's customer-history policy, and the rest of
89	/// the premium calculation does not need to know which clauses it is made of.
90	fn policy_modifier_rate_of(history: &CustomerHistory) -> f64 {
91	    let mut modifier_rate = FIRST_INSURANCE_SURCHARGE;
92	    if history.customer.years_with_mhpco >= LOYALTY_YEARS {
93	        modifier_rate -= LOYALTY_DISCOUNT;
94	    }
95	    if history.preceding_contracts > 0 {
96	        modifier_rate -= FOLLOW_UP_CONTRACT_DISCOUNT;
97	    }
98	    modifier_rate
99	}
100	
101	/// Policy-wide modifiers apply to the policy base premium, the sum of all item
102	/// base premiums, at the single rate the customer's standing earns.
103	fn with_policy_modifiers(history: &CustomerHistory, policy_base_premium: f64) -> f64 {
104	    policy_base_premium + policy_base_premium * policy_modifier_rate_of(history)
105	}
106	
107	/// A building block of 3 alike components is offered at a special base premium
108	/// instead of the per-component price.
109	fn alike_components_base_premium(count: usize) -> f64 {
110	    if count == COMPONENT_BLOCK_SIZE {
111	        return COMPONENT_BLOCK_BASE_PREMIUM;
112	    }
113	    count as f64 * COMPONENT_BASE_PREMIUM
114	}
115	
116	/// The policy base premium is the sum of all item base premiums, except that
117	/// alike components are priced together so the block offer can apply.
118	fn policy_base_premium_of(items: &[Item]) -> f64 {
119	    let main_items: f64 = items
120	        .iter()
121	        .filter(|item| !is_component(item))
122	        .map(base_premium_of)
123	        .sum();
124	    let components: f64 = alike_component_groups_of(items)
125	        .into_iter()
126	        .map(alike_components_base_premium)
127	        .sum();
128	    main_items + components
129	}
130	
131	/// Components count as alike when they are of exactly the same type, not
132	/// merely of the same family: a policy of 2 runes and 1 moonstone forms no
133	/// block, so the office prices the two kinds separately. This groups a
134	/// policy's components by type and reports how many are in each group, in
135	/// order of the groups' first appearance.
136	fn alike_component_groups_of(items: &[Item]) -> Vec<usize> {
137	    let mut groups: Vec<(&str, usize)> = Vec::new();
138	    for item in items.iter().filter(|item| is_component(item)) {
139	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
140	            Some((_, count)) => *count += 1,
141	            None => groups.push((&item.item_type, 1)),
142	        }
143	    }
144	    groups.into_iter().map(|(_, count)| count).collect()
145	}
146	
147	/// Only the final premium is rounded, and a premium is rounded up -- the
148	/// MHPCO's favor for money it collects. The processing fee is added at the very
149	/// end; being a whole number of G, it does not affect the rounding.
150	fn total_premium_of(premium_before_fee: f64) -> i64 {
151	    premium_before_fee.ceil() as i64 + PROCESSING_FEE
152	}
153	
154	/// The office was asked whether a risk surcharge on one item of a multi-item
155	/// policy burdens the whole policy, and ruled that it does not: an
156	/// item-specific modifier is measured against the base premium of the affected
157	/// item alone. A policy of a cursed sword and a plain amulet therefore carries
158	/// a curse surcharge of 50 G -- 50 % of the sword's own 100 G base premium --
159	/// and not 80 G, half of the 160 G policy base premium.
160	fn item_surcharges_of(items: &[Item]) -> f64 {
161	    items.iter().map(item_surcharge_of).sum()
162	}
163	
164	/// The risk surcharges an item carries: a curse adds 50 %, an enchantment at
165	/// or above the surcharge level adds 30 %, and an item that is both carries
166	/// both. The surcharge level is the premium side's own threshold; the claim
167	/// side judges enchantment against a separate level of its own.
168	fn item_surcharge_of(item: &Item) -> f64 {
169	    let mut surcharge_rate = 0.0;
170	    if item.cursed {
171	        surcharge_rate += CURSE_SURCHARGE;
172	    }
173	    if item.enchantment >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL {
174	        surcharge_rate += HIGH_ENCHANTMENT_SURCHARGE;
175	    }
176	    base_premium_of(item) * surcharge_rate
177	}
178	
179	/// How the two modifier families stack. By the office's scope ruling they are
180	/// measured against different bases, so they cannot be combined into one
181	/// percentage: the policy-wide modifiers scale the policy base premium, while
182	/// the item surcharges are shares of their own items' base premiums and are
183	/// added alongside. A cursed sword is therefore 100 + 10 % of 100 + 50 % of
184	/// 100, not 10 % of 150; a cursed sword beside a plain amulet is 160 + 10 % of
185	/// 160 + 50 % of 100.
186	fn premium_before_fee_of(history: &CustomerHistory, items: &[Item]) -> f64 {
187	    with_policy_modifiers(history, policy_base_premium_of(items)) + item_surcharges_of(items)
188	}
