190	/// The single customer a scenario's policies belong to.
191	struct Customer {
192	    years_with_mhpco: i64,
193	}
194	
195	/// The office's view of the customer at the moment of a quote: who they are
196	/// and how many contracts they already hold. The preceding-contract count is
197	/// not a property of the customer -- a scenario has one customer whose steps
198	/// are processed in order, so the count is what the office has on file when
199	/// this particular quote is drawn up. Together these are the facts the
200	/// customer-history policy reads.
201	struct CustomerHistory<'a> {
202	    customer: &'a Customer,
203	    preceding_contracts: usize,
204	}
