206	/// The MHPCO price list: the insurance value in G of a single insured item --
207	/// the worth the office acknowledges when it pays out, as opposed to the price
208	/// it charges to carry the risk. The price list prints the two figures side by
209	/// side, but they are separate rulings and move separately: the block offer and
210	/// the premium modifiers both change what an item costs to insure while leaving
211	/// its acknowledged worth untouched. So this list stays apart from the base
212	/// premium list rather than being derived from it. Both columns are now
213	/// complete: all four main types have their acknowledged worth on file, and a
214	/// claim or quote over an unlisted type is refused before it reaches the list,
215	/// so the remaining arm values the sword and nothing else -- a fall-through
216	/// rather than a `"sword"` arm for the same reason the base premium list uses
217	/// one, the list being closed.
218	fn insurance_value_of(item: &Item) -> i64 {
219	    if is_component(item) {
220	        return COMPONENT_INSURANCE_VALUE;
221	    }
222	    match item.item_type.as_str() {
223	        "amulet" => AMULET_INSURANCE_VALUE,
224	        "staff" => STAFF_INSURANCE_VALUE,
225	        "potion" => POTION_INSURANCE_VALUE,
226	        _ => SWORD_INSURANCE_VALUE,
227	    }
228	}
229	
230	/// The insurance sum is the sum of the insured items' insurance values. The
231	/// block offer discounts the premium only, never the insurance sum.
232	fn insurance_sum_of(items: &[Item]) -> i64 {
233	    items.iter().map(insurance_value_of).sum()
234	}
