279	#[derive(Deserialize)]
280	#[serde(rename_all = "camelCase")]
281	struct Incident {
282	    /// The office records what an incident was caused by, because the schema
283	    /// names `cause` among an incident's fields and binds that name. No clause
284	    /// of the price list or of the reimbursement rules reads it: what the
285	    /// office pays turns on the damaged item and the amount, never on whether
286	    /// the dragon attacked or the fire spread. The field stays on the document
287	    /// type all the same, so that type mirrors the schema it transcribes
288	    /// rather than only the part the clauses happen to consult. A clause that
289	    /// priced or reimbursed by cause would be the change that makes it read;
290	    /// until then the office asks nothing of a report that omits it, no
291	    /// example calling for such a report to be refused.
292	    #[allow(dead_code, reason = "bound by the normative input schema; no clause reads it")]
293	    cause: String,
294	    damages: Vec<ReportedDamage>,
295	}
