304	/// What one step of a scenario instructs the office to do, in the office's own
305	/// terms: draw up a policy over these insured items, or settle a claim of
306	/// these damages against the policy a named earlier step created. This is the
307	/// scenario's content once the document it arrived in has been read -- the
308	/// office processes instructions, not JSON, so the field names the schema
309	/// binds and the `serde` attributes that carry them stay on the document side
310	/// in `Step` and do not reach the processing rules.
311	enum Instruction {
312	    Quote { items: Vec<Item> },
313	    Claim { policy: usize, damages: Vec<Damage> },
314	}
315	
316	/// A policy a quote step drew up: the items it insures and the running
317	/// account of what the office has paid out on it. The account is part of the
318	/// policy and not of the scenario that processes it, because the cap is a
319	/// per-policy total: the specification has a sword's policy answer two claims
320	/// of 1500 G with 1400 G and then 600 G, so what an earlier claim drew is a
321	/// fact the policy itself carries into the next one.
322	struct DrawnUpPolicy {
323	    insured_items: Vec<Item>,
324	    paid_so_far: i64,
325	}
326	
327	impl DrawnUpPolicy {
328	    /// Settles a claim of these damages against this policy, which is one
329	    /// act and not two: the cap still available is what the policy has not
330	    /// yet paid, and a payout the office awards is paid out of it. So the
331	    /// policy's account is read and advanced here, where the settlement
332	    /// happens, rather than by the scenario that asks for it -- the
333	    /// specification's successive claims draw the cap down by what was
334	    /// actually awarded, which is a ruling of the cap and not of the step
335	    /// order. A reinstatement that restored part of the cap, or a cap drawn
336	    /// down by the desired rather than the awarded payout, would change this
337	    /// and nothing about how a scenario's steps are sequenced.
338	    fn settle_a_claim_of(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
339	        let settlement = claim(&self.insured_items, self.paid_so_far, damages)?;
340	        self.paid_so_far += settlement.payout;
341	        Ok(settlement)
342	    }
343	}
344	
345	/// The office's file of drawn-up policies, in which a policy is named by the
346	/// step that drew it up. The office was asked what a claim's `policy` names
347	/// and ruled for the step: the zero-based index of the quote step, not the
348	/// position of the policy among those drawn up -- a quote at step 2 is named
349	/// 2 even when it is only the second policy on file. So each policy is filed
350	/// under the number of the step that drew it up and found again by it. The
351	/// name is kept as a fact of the policy rather than left to its place in the
352	/// file, because the two differ: a scenario whose steps alternate quote and
353	/// claim files its second policy under 2, and only a recorded name says so.
354	///
355	/// The file answers two of the office's questions, and it is one fact asked
356	/// from two sides rather than two facts kept in step: a contract exists
357	/// exactly because a quote filed a policy, so the policies on file ARE the
358	/// contracts the customer holds. A claim reads the file by step to find the
359	/// policy to settle against; a quote asks how many policies stand on file to
360	/// learn how many contracts precede this one, which is what earns the
361	/// follow-up contract discount. The count is read off the file rather than
362	/// tallied beside it, so it cannot drift from what the file says. Only a
363	/// quote the office did not refuse reaches the file, so a refused quote is
364	/// neither claimable against nor counted as a preceding contract -- the same
365	/// ruling for both readings, because it is the same record.
366	#[derive(Default)]
367	struct PolicyFile {
368	    drawn_up: Vec<(usize, DrawnUpPolicy)>,
369	}
370	
371	impl PolicyFile {
372	    /// Files a policy over these items under the number of the quote step
373	    /// that drew it up, which is the name a later claim calls it by.
374	    fn draw_up_a_policy_over(&mut self, drawn_up_by_step: usize, insured_items: Vec<Item>) {
375	        self.drawn_up.push((
376	            drawn_up_by_step,
377	            DrawnUpPolicy {
378	                insured_items,
379	                paid_so_far: 0,
380	            },
381	        ));
382	    }
383	
384	    /// The policy a named step drew up, or the office's refusal when no step
385	    /// of that number drew one up.
386	    fn policy_drawn_up_by(&mut self, step: usize) -> Result<&mut DrawnUpPolicy, String> {
387	        self.drawn_up
388	            .iter_mut()
389	            .find(|(drawn_up_by_step, _)| *drawn_up_by_step == step)
390	            .map(|(_, policy)| policy)
391	            .ok_or_else(|| format!("no policy was created by step {step}"))
392	    }
393	
394	    /// How many contracts the customer holds: one per policy on file.
395	    fn contracts_on_file(&self) -> usize {
396	        self.drawn_up.len()
397	    }
398	}
