400	/// Processes a scenario's instructions in order and reports one result per
401	/// instruction. This is the office's scenario policy, and only that: the steps
402	/// are processed sequentially, each quote draws up a policy that a later claim
403	/// can name, and the premium a quote is charged depends on what the customer
404	/// already holds. Which policy a named step drew up, and how a step's number
405	/// becomes its policy's name, is the file's own knowledge -- see `PolicyFile`.
406	fn process_the_instructions(
407	    customer: &Customer,
408	    instructions: Vec<Instruction>,
409	) -> Result<Vec<StepResult>, String> {
410	    let mut results = Vec::new();
411	    let mut policies = PolicyFile::default();
412	    for (step, instruction) in instructions.into_iter().enumerate() {
413	        results.push(match instruction {
414	            Instruction::Quote { items } => {
415	                let history = CustomerHistory {
416	                    customer,
417	                    preceding_contracts: policies.contracts_on_file(),
418	                };
419	                let premium = quote(&history, &items)?;
420	                policies.draw_up_a_policy_over(step, items);
421	                StepResult::Quote { premium }
422	            }
423	            Instruction::Claim { policy, damages } => {
424	                let drawn_up = policies.policy_drawn_up_by(policy)?;
425	                let settlement = drawn_up.settle_a_claim_of(&damages)?;
426	                StepResult::Claim {
427	                    payout: settlement.payout,
428	                    remaining_cap: settlement.remaining_cap,
429	                }
430	            }
431	        });
432	    }
433	    Ok(results)
434	}
