436	/// Reads a scenario document, settles it, and writes the results document the
437	/// office publishes.
438	pub fn settle_the_scenario(scenario: &str) -> Result<String, String> {
439	    let results = run_scenario(scenario)?;
440	    let published = PublishedResults {
441	        results: results.iter().map(PublishedResult::from).collect(),
442	    };
443	    serde_json::to_string(&published).map_err(|error| error.to_string())
444	}
