452	/// One step's result as the office publishes it. The field names are the ones
453	/// the specification binds, so they are spelled here rather than derived.
454	#[derive(Serialize)]
455	#[serde(untagged)]
456	enum PublishedResult {
457	    Quote {
458	        premium: i64,
459	    },
460	    Claim {
461	        payout: i64,
462	        #[serde(rename = "remainingCap")]
463	        remaining_cap: i64,
464	    },
465	}
466	
467	impl From<&StepResult> for PublishedResult {
468	    fn from(result: &StepResult) -> Self {
469	        match *result {
470	            StepResult::Quote { premium } => PublishedResult::Quote { premium },
471	            StepResult::Claim {
472	                payout,
473	                remaining_cap,
474	            } => PublishedResult::Claim {
475	                payout,
476	                remaining_cap,
477	            },
478	        }
479	    }
480	}
