482	/// Reads a scenario document and reports one result per step. This is the
483	/// office's reading desk: it takes the document apart into the customer and
484	/// the instructions its steps give, and hands those to the processing rules.
485	fn run_scenario(scenario: &str) -> Result<Vec<StepResult>, String> {
486	    let scenario: Scenario = serde_json::from_str(scenario).map_err(|error| error.to_string())?;
487	    let customer = Customer {
488	        years_with_mhpco: scenario.customer.years_with_mhpco,
489	    };
490	    let instructions: Vec<Instruction> = scenario.steps.iter().map(instruction_of).collect();
491	    process_the_instructions(&customer, instructions)
492	}
493	
494	/// Translates one reported step into the instruction it gives the office.
495	fn instruction_of(step: &Step) -> Instruction {
496	    match step {
497	        Step::Quote { items } => Instruction::Quote {
498	            items: insured_items_of(items),
499	        },
500	        Step::Claim { policy, incident } => Instruction::Claim {
501	            policy: *policy,
502	            damages: reported_damages_of(&incident.damages),
503	        },
504	    }
505	}
506	
507	/// Translates the items a quote step reports into insured items.
508	fn insured_items_of(reported: &[ReportedItem]) -> Vec<Item> {
509	    reported
510	        .iter()
511	        .map(|item| Item {
512	            item_type: item.item_type.clone(),
513	            cursed: item.cursed,
514	            enchantment: item.enchantment,
515	            material: item.material.clone(),
516	        })
517	        .collect()
518	}
519	
520	/// Translates the damages an incident reports into damages.
521	fn reported_damages_of(reported: &[ReportedDamage]) -> Vec<Damage> {
522	    reported
523	        .iter()
524	        .map(|damage| Damage {
525	            item_type: damage.item_type.clone(),
526	            amount: damage.amount,
527	        })
528	        .collect()
529	}
