537	/// What the office settles on a claim: the payout in G and the cap still
538	/// available on the policy afterwards.
539	#[derive(Debug, PartialEq, Eq)]
540	struct Settlement {
541	    payout: i64,
542	    remaining_cap: i64,
543	}
