545	/// The office takes no damage report for a negative amount: a damage is what
546	/// the incident cost, so a negative figure is not a smaller claim but an
547	/// unreadable report, and the whole claim is refused.
548	fn admit_the_reported_damages(damages: &[Damage]) -> Result<(), String> {
549	    match damages.iter().find(|damage| damage.amount < 0) {
550	        Some(damage) => Err(format!("negative damage amount: {}", damage.amount)),
551	        None => Ok(()),
552	    }
553	}
