555	/// How the office settles a claim against this policy. One incident may
556	/// damage several insured items, and the office settles each damaged item on
557	/// its own terms before adding the amounts up: a dragon attack on a sword and
558	/// an amulet is settled as two damages, not as one. The awarded sum is then
559	/// held back to the cap still available, which is the policy's cap less what
560	/// earlier claims have already drawn on it -- a policy may be claimed against
561	/// more than once, so what has been paid so far is a fact of every claim, nil
562	/// on the first.
563	fn claim(
564	    items: &[Item],
565	    paid_so_far: i64,
566	    damages: &[Damage],
567	) -> Result<Settlement, String> {
568	    admit_the_reported_damages(damages)?;
569	    let cap_available = payout_cap_of(items)? - paid_so_far;
570	    let payout = desired_payout_of(items, damages)?.min(cap_available);
571	    Ok(Settlement {
572	        payout,
573	        remaining_cap: cap_available - payout,
574	    })
575	}
