585	/// which is how the office holds an insured item to a single damage; see
586	/// `insured_item_answering`.
587	fn desired_payout_of(items: &[Item], damages: &[Damage]) -> Result<i64, String> {
588	    let mut unanswered: Vec<&Item> = items.iter().collect();
589	    let mut desired_payout = 0;
590	    for damage in damages {
591	        let damaged_item = insured_item_answering(&mut unanswered, damage)?;
592	        desired_payout += reimbursement_of(damaged_item, damage);
593	    }
594	    Ok(desired_payout)
595	}
