718	/// wording without giving any caller a decision it can make. A caller that had
719	/// to tell the reasons apart -- a different exit code per reason, a retry on
720	/// some but not others -- would be the change that earns the type.
721	fn quote(history: &CustomerHistory, items: &[Item]) -> Result<i64, String> {
722	    admit_the_listed_items(items)?;
723	    Ok(total_premium_of(premium_before_fee_of(history, items)))
724	}
